Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Muro de tarjetas KPI con bullet chart IBCS y cross-filter por clic.",
  "width": 860,
  "height": 470,
  "padding": 0,
  "autosize": {
    "type": "none",
    "contains": "padding"
  },
  "config": {
    "text": {
      "font": "Segoe UI, Inter, -apple-system, Helvetica Neue, sans-serif"
    }
  },
  "signals": [
    {
      "name": "topN",
      "value": 6,
      "bind": {
        "input": "range",
        "min": 3,
        "max": 12,
        "step": 1,
        "name": "Top N  "
      }
    },
    {
      "name": "headerH",
      "update": "clamp(height * 0.15, 54, 76)"
    },
    {
      "name": "labelW",
      "update": "clamp(width * 0.34, 170, 320)"
    },
    {
      "name": "rightW",
      "update": "clamp(width * 0.20, 112, 190)"
    },
    {
      "name": "barX0",
      "update": "labelW + 14"
    },
    {
      "name": "barX1",
      "update": "max(barX0 + 60, width - rightW - 16)"
    },
    {
      "name": "footerH",
      "update": "26"
    }
  ],
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "kpi",
      "source": "dataset",
      "transform": [
        {
          "type": "filter",
          "expr": "isValid(datum[''Categoría'']) && isValid(datum.Real)"
        },
        {
          "type": "formula",
          "as": "cumpl",
          "expr": "isValid(datum.Objetivo) && datum.Objetivo != 0 ? datum.Real / datum.Objetivo : null"
        },
        {
          "type": "formula",
          "as": "varPy",
          "expr": "isValid(datum[''Año anterior'']) && datum[''Año anterior''] != 0 ? datum.Real / datum[''Año anterior''] - 1 : null"
        },
        {
          "type": "formula",
          "as": "tono",
          "expr": "datum.cumpl == null ? ''#5B6675'' : datum.cumpl >= 1 ? ''#0F766E'' : datum.cumpl >= 0.97 ? ''#B45309'' : ''#BE123C''"
        },
        {
          "type": "formula",
          "as": "op",
          "expr": "datum.__selected__ == ''off'' ? 0.32 : 1"
        },
        {
          "type": "formula",
          "as": "activa",
          "expr": "datum.__selected__ == ''on''"
        },
        {
          "type": "window",
          "ops": [
            "dense_rank"
          ],
          "as": [
            "puesto"
          ],
          "sort": {
            "field": "Real",
            "order": "descending"
          }
        },
        {
          "type": "filter",
          "expr": "datum.puesto <= topN"
        }
      ]
    },
    {
      "name": "resumen",
      "source": "kpi",
      "transform": [
        {
          "type": "formula",
          "as": "unoSel",
          "expr": "datum.__selected__ == ''on'' ? 1 : 0"
        },
        {
          "type": "aggregate",
          "fields": [
            "Real",
            "Año anterior",
            "unoSel",
            "Categoría"
          ],
          "ops": [
            "sum",
            "sum",
            "sum",
            "count"
          ],
          "as": [
            "tReal",
            "tPy",
            "tSel",
            "tN"
          ]
        },
        {
          "type": "formula",
          "as": "tVar",
          "expr": "datum.tPy != 0 ? datum.tReal / datum.tPy - 1 : null"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "linear",
      "zero": true,
      "nice": true,
      "round": true,
      "domain": {
        "fields": [
          {
            "data": "kpi",
            "field": "Real"
          },
          {
            "data": "kpi",
            "field": "Objetivo"
          },
          {
            "data": "kpi",
            "field": "Año anterior"
          }
        ]
      },
      "range": {
        "signal": "[barX0, barX1]"
      }
    },
    {
      "name": "y",
      "type": "band",
      "round": true,
      "paddingInner": 0.17,
      "paddingOuter": 0.04,
      "domain": {
        "data": "kpi",
        "field": "Categoría",
        "sort": {
          "op": "max",
          "field": "Real",
          "order": "descending"
        }
      },
      "range": {
        "signal": "[headerH, height - footerH]"
      }
    }
  ],
  "marks": [
    {
      "name": "cabeceraEtiqueta",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "value": 2
          },
          "y": {
            "value": 6
          },
          "baseline": {
            "value": "top"
          },
          "align": {
            "value": "left"
          },
          "text": {
            "signal": "''TOTAL · '' + datum.tN + '' CATEGORÍAS''"
          },
          "fontSize": {
            "value": 10
          },
          "fontWeight": {
            "value": 700
          },
          "fill": {
            "value": "#5B6675"
          }
        }
      }
    },
    {
      "name": "cabeceraValor",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "value": 2
          },
          "y": {
            "signal": "headerH - 16"
          },
          "baseline": {
            "value": "alphabetic"
          },
          "align": {
            "value": "left"
          },
          "text": {
            "signal": "pbiFormat(datum.tReal, ''#,0,,.00M'')"
          },
          "fontSize": {
            "signal": "clamp(headerH * 0.42, 20, 30)"
          },
          "fontWeight": {
            "value": 700
          },
          "fill": {
            "value": "#0F172A"
          }
        }
      }
    },
    {
      "name": "cabeceraVariacion",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "width - 2"
          },
          "y": {
            "signal": "headerH - 18"
          },
          "baseline": {
            "value": "alphabetic"
          },
          "align": {
            "value": "right"
          },
          "text": {
            "signal": "datum.tVar == null ? \"\" : (datum.tVar >= 0 ? ''▲ +'' : ''▼ −'') + pbiFormat(abs(datum.tVar), ''0.0%'') + '' vs año anterior''"
          },
          "fontSize": {
            "value": 12
          },
          "fontWeight": {
            "value": 600
          },
          "fill": {
            "signal": "datum.tVar == null ? ''#4B5563'' : datum.tVar >= 0 ? ''#0F766E'' : ''#BE123C''"
          }
        }
      }
    },
    {
      "name": "cabeceraPista",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "width - 2"
          },
          "y": {
            "value": 6
          },
          "baseline": {
            "value": "top"
          },
          "align": {
            "value": "right"
          },
          "text": {
            "signal": "datum.tSel > 0 ? datum.tSel + '' de '' + datum.tN + '' seleccionada · clic de nuevo para limpiar'' : ''Clic en una tarjeta para filtrar el informe''"
          },
          "fontSize": {
            "value": 10.5
          },
          "fontWeight": {
            "value": 500
          },
          "fill": {
            "value": "#5B6675"
          }
        }
      }
    },
    {
      "name": "cabeceraLinea",
      "type": "rule",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "signal": "headerH - 9"
          },
          "stroke": {
            "value": "#E2E8F0"
          },
          "strokeWidth": {
            "value": 1
          }
        }
      }
    },
    {
      "name": "tarjeta",
      "type": "rect",
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "value": 1
          },
          "x2": {
            "signal": "width - 1"
          },
          "y": {
