            "field": "Categoría"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "cornerRadius": {
            "value": 14
          },
          "fill": {
            "signal": "datum.activa ? ''#F2F7FF'' : ''#FFFFFF''"
          },
          "stroke": {
            "signal": "datum.activa ? ''#8FB2E6'' : ''#E8EDF5''"
          },
          "strokeWidth": {
            "signal": "datum.activa ? 1.6 : 1"
          },
          "opacity": {
            "field": "op"
          },
          "cursor": {
            "value": "pointer"
          },
          "tooltip": {
            "signal": "{''title'': datum[''Categoría''], ''Real'': pbiFormat(datum.Real, ''#,0''), ''Objetivo'': pbiFormat(datum.Objetivo, ''#,0''), ''Año anterior'': pbiFormat(datum[''Año anterior''], ''#,0''), ''Cumplimiento del objetivo'': datum.cumpl == null ? ''—'' : pbiFormat(datum.cumpl, ''0.0%''), ''Variación vs año anterior'': datum.varPy == null ? ''—'' : pbiFormat(datum.varPy, ''0.0%'')}"
          }
        }
      }
    },
    {
      "name": "franja",
      "type": "rect",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "value": 1
          },
          "width": {
            "value": 4
          },
          "y": {
            "scale": "y",
            "field": "Categoría"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "cornerRadius": {
            "value": 2
          },
          "fill": {
