          "text": {
            "signal": "datum.cumpl == null ? ''sin objetivo'' : pbiFormat(datum.cumpl, ''0.0%'') + '' del objetivo''"
          },
          "limit": {
            "signal": "labelW - 26"
          },
          "fontSize": {
            "value": 10.5
          },
          "fontWeight": {
            "value": 600
          },
          "fill": {
            "field": "tono"
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "pista",
      "type": "rect",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "barX0"
          },
