          },
          "x2": {
            "scale": "x",
            "field": "Año anterior"
          },
          "y": {
            "scale": "y",
            "field": "Categoría",
            "band": 0.5,
            "offset": 3
          },
          "height": {
            "value": 7
          },
          "cornerRadius": {
            "value": 3.5
          },
          "fill": {
            "value": "#7E8DA0"
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
