      "type": "rect",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "barX0"
          },
          "x2": {
            "scale": "x",
            "field": "Real"
          },
          "y": {
            "scale": "y",
            "field": "Categoría",
            "band": 0.5,
            "offset": -11
          },
          "height": {
            "value": 11
          },
          "cornerRadius": {
            "value": 5.5
          },
          "fill": {
            "value": {
              "gradient": "linear",
              "x1": 0,
              "y1": 0,
              "x2": 1,
              "y2": 0,
              "stops": [
                {
                  "offset": 0,
                  "color": "#2E6BE0"
                },
                {
                  "offset": 1,
                  "color": "#16307A"
                }
              ]
            }
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "objetivo",
      "type": "rule",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "field": "Objetivo"
          },
          "y": {
            "scale": "y",
            "field": "Categoría",
            "band": 0.5,
            "offset": -17
          },
          "y2": {
            "scale": "y",
            "field": "Categoría",
            "band": 0.5,
            "offset": 17
          },
          "stroke": {
            "value": "#0F172A"
          },
          "strokeWidth": {
            "value": 2.5
          },
          "strokeCap": {
            "value": "round"
          },
          "opacity": {
            "signal": "isValid(datum.Objetivo) ? datum.op : 0"
